import{_ as o,a0 as p,w as i,s as d,ao as a,I as r,x as e,a1 as u,A as s}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const _=JSON.parse('{"title":"每日Ubuntu小技巧——添加用户到已存在的组 | LCTT x X-CMD","titleTemplate":false,"description":"每日Ubuntu小技巧——添加用户到已存在的组 | LCTT (201310) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"每日Ubuntu小技巧——添加用户到已存在的组 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"每日Ubuntu小技巧——添加用户到已存在的组 | LCTT (201310) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201310/Daily Ubuntu Tips – Adding Users To Existing Groups","title":"每日Ubuntu小技巧——添加用户到已存在的组","tag":"201310","desc":""},"relativePath":"201310/Daily Ubuntu Tips – Adding Users To Existing Groups.md","filePath":"[post].md"}'),l={name:"201310/Daily Ubuntu Tips – Adding Users To Existing Groups.md"};function g(b,t,T,m,x,U){const n=p("Link");return i(),d("div",null,[t[11]||(t[11]=a(`<h1 id="每日ubuntu小技巧——添加用户到已存在的组" tabindex="-1">每日Ubuntu小技巧——添加用户到已存在的组 <a class="header-anchor" href="#每日ubuntu小技巧——添加用户到已存在的组" aria-label="Permalink to “每日Ubuntu小技巧——添加用户到已存在的组”">​</a></h1><p>对于刚开始使用Ubuntu的用户和新手来说，尤其是从Ubuntu中不在包含旧式的用户和组的管理工具后，管理用户和组变的富有挑战性。在先前Ubuntu的版本下，用户可以通过Gnome系统工具下的用户管理工具轻松的管理用户和组。</p><p>现在，在Ubuntu上没有了这个工具，现在唯一的工具也仅仅允许你创建、管理和删除用户，所以如果你需要在Ubuntu中从组里面添加或删除用户，那么你将需要用到命令行终端或控制台。</p><p>举个例子，如果你想要让某些用户访问文件或提升他们的访问权限，最好方式就是改变组的权限。你可以创建一个组，接着给这个组正确的权限，在添加用户到组时，用户可以获得与组相同的权限。</p><p>因为当前Ubuntu不能用工具轻易的管理组权限，这个简洁的教程，将告诉你如何用命令行完成以上操作，这仅仅是一行代码，一旦你理解了，这并不难。</p><p>开始吧，按<strong>Ctrl-Alt-T</strong>打开终端。</p><p>查看Ubuntu上所有的组，键入命令<code>groupmod</code>并（<strong>连按三次tab键</strong>）</p><pre><code>groupmod &lt;连按三次tab键&gt;
</code></pre><p><img src="http://www.liberiangeek.net/wp-content/uploads/2013/09/groupsubuntuadduser.png" alt=""></p><p>这会列出现在你系统上的所有用户组，现在添加用户到已存在的组吧，运行下列命令：</p><pre><code>sudo adduser 用户名 组名
</code></pre><p>例如，如果你想添加Richard到sudo组，运行下列命令：</p><pre><code>sudo adduser richard sudo
</code></pre><p>好了，去验证用户的相关组，运行下列命令：</p><pre><code>id richard
</code></pre><p>试试吧!</p><hr>`,17)),r("p",null,[t[1]||(t[1]=e("via: ",-1)),u(n,{href:"http://www.liberiangeek.net/2013/09/daily-ubuntu-tips-adding-users-existing-groups/"},{default:s(()=>[...t[0]||(t[0]=[e("http://www.liberiangeek.net/2013/09/daily-ubuntu-tips-adding-users-existing-groups/",-1)])]),_:1})]),r("p",null,[t[4]||(t[4]=e("本文由 ",-1)),u(n,{href:"https://github.com/LCTT/TranslateProject"},{default:s(()=>[...t[2]||(t[2]=[e("LCTT",-1)])]),_:1}),t[5]||(t[5]=e(" 原创翻译，",-1)),u(n,{href:"http://linux.cn/"},{default:s(()=>[...t[3]||(t[3]=[e("Linux中国",-1)])]),_:1}),t[6]||(t[6]=e(" 荣誉推出",-1))]),r("p",null,[t[9]||(t[9]=e("译者：",-1)),u(n,{href:"https://github.com/Luoxcat"},{default:s(()=>[...t[7]||(t[7]=[e("Luoxcat",-1)])]),_:1}),t[10]||(t[10]=e(" 校对：",-1)),u(n,{href:"https://github.com/wxy"},{default:s(()=>[...t[8]||(t[8]=[e("wxy",-1)])]),_:1})])])}const w=o(l,[["render",g]]);export{_ as __pageData,w as default};
